globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.acceptedAnswers ? {acceptedAnswers: row.acceptedAnswers} : {}),
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(row.textAnswer !== undefined ? {textAnswer: row.textAnswer} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(row.acceptedNumericAnswers ? {acceptedNumericAnswers: row.acceptedNumericAnswers} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + (group.originalNumbers ? group.start : 1)), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.solutionsFile ? {solutionUrl: folder + meta.solutionsFile} : {}),
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

const edition = globalThis.makeSubjectEdition({"subject":"kit","year":2018,"grade":"8-9","contest":"КИТ","letters":"АБВГ","count":26,"language":"ru","points":3,"tasksFile":"8-9.pdf","answersFile":"reviewed-8-9.pdf","sections":[{"start":1,"title":"3 балла · № 1–5"},{"start":6,"title":"3 балла · № 6–10"},{"start":11,"title":"4 балла · № 11–15"},{"start":16,"title":"4 балла · № 16–20"},{"start":21,"title":"5 баллов · № 21–23"},{"start":24,"title":"Числовой ответ · № 24–26"}],"reviewedKey":true}, [{"title":"Мышка в трёх сказках","question":"В левом круге разместили героев сказки «Колобок», в правом — «Курочка Ряба», в нижнем — «Теремок». В какой части рисунка располагается мышка?","choices":["А","Б","В","Г"],"points":3,"steps":["Мышка участвует в «Курочке Рябе» и в «Теремке». В «Колобке» мышка не встречается.","Нужна область внутри правого и нижнего кругов, но вне левого. На схеме эта часть помечена В."],"answer":2,"figure":{"src":"assets/kit/2018/8-9-01.webp","alt":"Круги «Колобок», «Курочка Ряба», «Теремок». А — общее пересечение, Б — только левый и нижний, В — только правый и нижний, Г — только левый и правый.","width":315,"height":198}},{"title":"Двоичная запись","question":"Какая запись числа невозможна в двоичной системе счисления?","choices":["1","10","22","101"],"points":3,"steps":["При основании 2 разрешены только цифры 0 и 1. В записях 1, 10 и 101 других цифр нет.","В записи 22 есть цифра 2. Она не может входить в двоичную запись."],"answer":2},{"title":"Домен островного государства","question":"Крошечное островное государство Тувалу с населением около 10000 человек успешно продаёт на международном рынке…","choices":["национальный домен верхнего уровня","электронные переводчики","материнские платы","программы-антивирусы"],"points":3,"steps":["У Тувалу есть национальное окончание интернет-адресов .tv. По-английски TV также обозначает телевидение.","Из-за этого .tv интересует сайты и службы, связанные с видео. На международном рынке регистрируют имена в этом национальном домене верхнего уровня."],"answer":0},{"title":"Телефоны на картинке","question":"Сколько всего телефонов изображено на рисунке?","choices":["1","5","6","7"],"points":3,"steps":["Слева мобильный телефон. Далее видны настенные и настольные телефоны с дисками, кнопками и отдельными трубками.","У всех семи изображений есть признаки телефонного аппарата. Нет ни одного игрового контроллера или другого устройства."],"answer":3,"figure":{"src":"assets/kit/2018/8-9-04.webp","alt":"Семь устройств: один мобильный аппарат, три настольных и три настенных телефонных аппарата разных лет.","width":1146,"height":153}},{"title":"Знак в нотах","question":"Какой из этих символов используется в музыкальной нотации?","choices":["#","$","@","&"],"points":3,"steps":["Знак диеза повышает ноту на полтона. Он выглядит как две пересекающиеся пары линий, ♯.","При наборе простым текстом диез передают похожим знаком #. Другие перечисленные символы не похожи на знаки изменения высоты ноты."],"answer":0},{"title":"Место в кинотеатре","question":"Дан план зала кинотеатра, в котором не указан экран. Коля и Петя сидят на закрашенных местах. Коля сидит во втором ряду на третьем месте. Каков номер места Пети?","choices":["5","6","3","4"],"points":3,"steps":["Из двух отметок третьей с края может быть нижняя: она третья справа. Значит, это место Коли, а второй ряд считают снизу.","Другая отметка — место Пети. Она четвёртая слева из восьми, то есть пятая справа."],"answer":0,"figure":{"src":"assets/kit/2018/8-9-06.webp","alt":"Четыре ряда по восемь мест. Чёрные клетки: четвёртая слева во втором ряду сверху и шестая слева в третьем ряду сверху.","width":291,"height":162}},{"title":"Вычисления на ферме","question":"Для майнинг-фермы необходимо большое количество…","choices":["коров","видеокарт","мониторов","лопат"],"points":3,"steps":["В задаче речь о вычислительных установках. Многие операции можно распределить между большим количеством параллельных вычислителей.","Видеокарты имеют много вычислительных блоков. Именно их используют в описанной майнинг-ферме."],"answer":1},{"title":"Расширение файла","question":"По умолчанию файл с расширением .rar является…","choices":["браузером","архивом","антивирусом","презентацией"],"points":3,"steps":["В файле RAR несколько файлов могут быть собраны под одним именем и сжаты.","Расширение .rar обозначает архив. Его можно распаковать и получить содержимое."],"answer":1},{"title":"Три дня рождения","question":"Юра, Ия и Оля родились 5.03, 5.07 и 31.07. Юра и Ия родились одного и того же числа, а у Ии и Оли дни рождения — в разные месяцы. Кто в какой день родился?","choices":["Юра — 5.07, Ия — 5.03, Оля — 31.07","Юра — 5.03, Ия — 5.07, Оля — 31.07","Юра — 31.07, Ия — 5.03, Оля — 5.07","Юра — 5.07, Ия — 31.07, Оля — 5.03"],"points":3,"steps":["Юра и Ия родились пятого числа. Оле остаётся 31 июля.","День рождения Ии в другом месяце, чем у Оли, поэтому Ия родилась 5 марта. Юра родился 5 июля."],"answer":0},{"title":"Порядок по весу","question":"На рисунке приведены результаты взвешиваний пяти ящиков. Упорядочьте ящики по возрастанию веса.","choices":["1-2-3-4-5","1-3-4-5-2","2-5-4-3-1","3-4-5-1-2"],"points":3,"steps":["Ящик на опустившейся стороне тяжелее. Получаем цепочку 1 > 3 > 4 > 5 > 2.","Для возрастания начни с самого лёгкого, 2. Затем 5, 4, 3, 1. Получается 2–5–4–3–1."],"answer":2,"figure":{"src":"assets/kit/2018/4-5-08.webp","alt":"На весах попарно стоят ящики: 1 внизу, 3 вверху. 4 внизу, 5 вверху. 4 вверху, 3 внизу. 2 вверху, 5 внизу.","width":1122,"height":126}},{"title":"Мониторы и видеопамять","question":"При покупке некоего устройства Вася учитывал количество поддерживаемых мониторов, объём и тип памяти. Что покупал Вася?","choices":["клавиатуру","видеокарту","мышь","жёсткий диск"],"points":4,"steps":["Количество подключённых мониторов зависит от видеовыходов устройства. Также устройству может требоваться собственная память для обработки изображения.","Оба признака относятся к видеокарте. Клавиатура и мышь выполняют ввод, жёсткий диск хранит файлы."],"answer":1},{"title":"Порт DVI","question":"Через порт DVI к компьютеру подключают…","choices":["монитор","клавиатуру","микрофон","мышь"],"points":4,"steps":["DVI передаёт видеосигнал от компьютера к дисплею. Для этой передачи нужен видеовыход на компьютере и вход дисплея.","Из перечисленных устройств дисплей — монитор. Остальные устройства выполняют ввод."],"answer":0},{"title":"Размер и скорость записи","question":"Скорость записи информации USB-накопителя с интерфейсом USB 2.0 равна 128 Мбит/с, что позволило записать файл kit.exe за 64 секунды. На USB-накопитель с интерфейсом USB 3.0 файл kot.exe объёмом 512 Мбайт был записан за 4 секунды. За сколько секунд запишется kit.exe на USB-накопитель с интерфейсом USB 3.0?","choices":["1","2","8","4"],"points":4,"steps":["Размер kit.exe равен 128 × 64 = 8192 Мбит. В байте 8 бит, значит, это 1024 Мбайт.","Скорость USB 3.0 по второму файлу равна 512 ÷ 4 = 128 Мбайт/с. Для первого файла нужно 1024 ÷ 128 = 8 секунд."],"answer":2},{"title":"Сгоревшие вертикали","question":"Цифры на экране калькулятора отображаются при помощи ячеек. Каждая ячейка состоит из 3 горизонтальных, 4 вертикальных и 2 диагональных перекладин, как показано на рисунке. Сколько всего различных цифр можно определить в ячейке однозначно, если перегорят все вертикальные перекладины этой ячейки?","choices":["6","7","8","10"],"points":4,"steps":["Если убрать вертикальные линии, у 5 и 8 остаются одинаковые три горизонтали. Эти две цифры уже нельзя определить однозначно.","Остальные восемь различаются горизонталями или диагоналями. Например, 1 оставит только верхнюю диагональ, а 7 ту же диагональ и верхнюю горизонталь. Однозначно читаются восемь цифр."],"answer":2,"figure":{"src":"assets/kit/2018/4-5-16.webp","alt":"Цифры от 0 до 9 в ячейках с верхней и нижней диагоналями.","width":567,"height":99}},{"title":"Две кнопки калькулятора","question":"В клубе любителей числа 2 создали калькулятор, который всегда начинает свою работу с числа 2 и имеет две кнопки: «прибавить 2» и «умножить на 2». За какое минимальное количество нажатий кнопок калькулятора можно получить число 260?","choices":["8","9","11","129"],"points":4,"steps":["С любого чётного числа начиная с 2 удвоение даёт не меньший результат, чем прибавление 2. Верхняя граница после семи нажатий — 2 × 2⁷ = 256.","Дойди шестью удвоениями до 128, прибавь 2 и удвой 130. Получится 260 за восемь нажатий."],"answer":0},{"title":"Кабели с петлями","question":"Монтажник Петров, доставая сетевые кабели из сумки, обнаружил следующую картину. Какие кабели завяжутся в узел, если аккуратно потянуть за концы в разные стороны?","choices":["1, 2, 3, 4","2","2, 4","2, 3"],"points":4,"steps":["По рисунку 1 петли расправляются: пересекающиеся ветви можно раздвинуть без пропускания конца через кольцо. Рисунок 2 отличается местом верхнего пересечения: там конец удерживается петлёй.","В рисунке 3 конец тоже проходит сквозь замкнутый изгиб и затянет его. В рисунке 4 видимые окружности представляют собой свободные изгибы, они расправятся. Завяжутся 2 и 3."],"answer":3,"figures":[{"src":"assets/kit/2018/6-7-23-one.webp","alt":"Две вытянутые петли, в верхнем пересечении поперечная линия непрерывна.","width":195,"height":204,"caption":"Кабель 1"},{"src":"assets/kit/2018/6-7-23-two.webp","alt":"Две вытянутые петли, в верхнем пересечении поперечная линия прерывается.","width":198,"height":210,"caption":"Кабель 2"},{"src":"assets/kit/2018/6-7-23-three.webp","alt":"Вертикальные и боковые петли с несколькими пересечениями.","width":222,"height":234,"caption":"Кабель 3"},{"src":"assets/kit/2018/6-7-23-four.webp","alt":"Округлые изгибы, один свободный конец внизу.","width":195,"height":192,"caption":"Кабель 4"}]},{"title":"Число на суаньпане","question":"Перед вами китайские счёты — суаньпань, на которых отложены различные числа. На картинке слева — число 16317. Какое число отложено на счётах на картинке справа?","choices":["11312","61812","21311","21816"],"points":4,"steps":["К поперечной планке придвигают косточки, которые участвуют в числе. Каждая верхняя косточка стоит 5, каждая нижняя — 1.","Последние пять стержней дают 5 + 1, затем 1, затем 5 + 3, затем 1 и 2. Слева от них нули. Читаем 61812."],"answer":1,"figures":[{"src":"assets/kit/2018/8-9-17-example.webp","alt":"Левые счёты показывают 16317.","width":354,"height":212,"caption":"Число 16317"},{"src":"assets/kit/2018/8-9-17-unknown.webp","alt":"Счёты для задания. Активны пять правых стержней.","width":351,"height":216,"caption":"Число для чтения"}]},{"title":"Три кнопки замка","question":"В кодовом замке имеются три кнопки: 1, 2 и 3. Дверь открывается, если в набранной последовательности две подряд идущие цифры образуют правильный код — какое-то двузначное число. Какое наименьшее число нажатий кнопок необходимо, чтобы наверняка открыть дверь?","choices":["10","11","12","18"],"points":4,"steps":["Из трёх кнопок получается 3 × 3 = 9 разных пар. После k нажатий есть только k − 1 соседних пар. Нужно хотя бы десять нажатий.","Последовательность 1121322331 проверяет 11, 12, 21, 13, 32, 22, 23, 33, 31. Все девять пар встречаются за десять нажатий."],"answer":0},{"title":"Три замены букв","question":"Петя в текстовом редакторе три раза применил инструмент «Заменить всё» к фразе «на дворе трава, на траве дрова». Сначала он применил «д заменить на я», потом «т заменить на д» и, наконец, «я заменить на т». В результате получилось…","choices":["на дворе трава, на траве дрова","на творе драва, на драве трова","на дворе драва, на драве дрова","на творе трава, на траве трова"],"points":4,"steps":["Буквы «д» временно отложены под буквой «я», которой сначала в тексте нет. Поэтому следующая команда меняет только изначальные «т» на «д».","Последняя команда превращает временные «я» в «т». Исходные «д» и «т» обменялись. Получилось «на творе драва, на драве трова»."],"answer":1},{"title":"Память калькулятора","question":"Фёдор, нажав последовательно на клавиши MC, 2, ×, 4, M+, 7, M+, MR калькулятора, получил 15. Что получится в результате последовательного нажатия на клавиши MC, 2, M+, 3, ×, 5, M+, MR?","choices":["0","10","25","17"],"points":4,"steps":["MC удаляет прежнее значение из памяти. Первый M+ сохраняет число 2.","Второй M+ добавляет результат 3 × 5 = 15. MR показывает сумму 2 + 15 = 17."],"answer":3},{"title":"Разность в двоичной записи","question":"Вычислите 100000₂ − 11111₂.","choices":["1₂","1000000₂","11111₂","11110₂"],"points":5,"steps":["Число 100000₂ равно 32. Число 11111₂ на единицу меньше, потому что прибавление единицы к цепочке из пяти единиц даёт 100000₂.","Разность этих соседних чисел равна 1, в двоичной записи также 1₂."],"answer":0},{"title":"Пропущенная буква","question":"При кодировании текста Дима заменял одинаковые буквы одинаковыми цифрами, а разные буквы — разными цифрами. Какую фразу закодировал Дима, если известно, что получилось 12134 56474, но при этом он пропустил одну букву в тексте?","choices":["кукла копала","папка пропала","шашка попала","сестра упала"],"points":5,"steps":["У кода 12134 повторяется только первая и третья буква. Код 56474 требует повтора третьей и пятой букв, обе должны обозначаться цифрой 4, как последняя буква первого слова.","Убери «р» из слова «сестра»: «сеста» подходит как С=1, Е=2, Т=3, А=4. «Упала» дополняет соответствия У=5, П=6, Л=7. У других вариантов после удаления одной буквы нет обоих нужных повторов с разными цифрами для разных букв."],"answer":3},{"title":"Счётчик цикла","question":"Дан фрагмент кода:\n\nint a=1; while(a<9) a=a+1; cout<<a;\n\nКакой из фрагментов выводит в консоль тот же результат?","choices":["int a=1; for(; a<10; ++a); cout<<a;","int a=1; for(int a=1; a<9; a++); cout<<a;","int a=1; for(; a<9; a=a+1); cout<<a;","int a=1; for(int a=1; a<=9; a=a+1); cout<<a;"],"points":5,"steps":["В исходном while переменная a растёт с 1 до 9. При 9 условие a < 9 перестаёт выполняться, и cout выводит 9.","В А цикл доходит до 10. В Б и Г объявляется другая переменная a только внутри for, поэтому снаружи печатается 1. В В используется внешняя a и та же граница 9."],"answer":2},{"title":"Ручка в пяти пеналах","question":"Юра спрятал ручку в один из пяти пеналов, а Петя должен найти её. Он открывает один из пеналов. Если там лежит ручка, то игра окончена. Если ручки нет, то пенал закрывают, Петя отворачивается, а Юра перекладывает ручку в соседний пенал справа (из пенала 5 ручка не перекладывается). Далее Петя снова открывает какой-то пенал. За какое минимальное количество открываний пеналов Петя точно найдёт ручку?","choices":[],"points":5,"steps":["Открывай пеналы 1, 3, 5. Если первая проба неудачна, после сдвига ручка будет в 3, 4 или 5. Если ручки нет в 3, следующий сдвиг помещает её в 5.","За один неудачный ход проверка исключает не больше одного возможного места, а сдвиг сливает не больше двух мест в одно, только 4 и 5. После первой пробы возможны минимум три места. Одной следующей пробой их не проверить. Нужно три."],"numericAnswer":3},{"title":"Три красные бусинки","question":"Подсчитайте количество различных ожерелий из 3 красных и 5 синих бусинок. Ожерелья считаются одинаковыми, если одно ожерелье может быть получено из другого передвижением бусинок по кольцу или переворачиванием ожерелья.","choices":[],"points":5,"steps":["Между тремя красными есть три дуги с синими бусинками. Их длины в сумме 5. Повороты и перевороты дают любую перестановку трёх длин.","В порядке возрастания длины могут быть (0,0,5), (0,1,4), (0,2,3), (1,1,3), (1,2,2). Всего пять троек."],"numericAnswer":5},{"title":"Отступы в Python","question":"Распечатывая приведённый ниже код на языке программирования Python, Вася не заметил, что переносы строк и отступы, которые критически важны в этом языке, удалились. Какое наименьшее общее количество отступов надо «вернуть» в этот код, чтобы он правильно решал задачу — выводил простые числа? Запишите заголовок каждого цикла или условия и его тело на разных строках.\n\nn = input()\nfor i in xrange(2, n+1): k = 0 for j in xrange(2, i):\nif i % j == 0: k = k + 1 if k == 0: print(i)\n\nПодсказка. В приведённом ниже фрагменте кода три отступа:\nfor number in range(10):\n    if number % 2 == 0:\n        print(number)","choices":[],"points":5,"steps":["Во внешнем цикле для каждого i обнуляем k и перебираем j. «k = 0» и «for j» стоят на уровне 1, проверка остатка на уровне 2, увеличение k — на уровне 3.","После всех j условие «if k == 0» ещё находится внутри внешнего цикла на уровне 1. Вывод числа — на уровне 2. Складываем отступы по примеру: 1 + 1 + 2 + 3 + 1 + 2 = 10."],"numericAnswer":10,"adaptation":"Уточнено, что тело каждого цикла или условия начинается с новой строки, как в примере."}]);
